<?php
declare(strict_types=1);
final class DcpToolExecutionService {
 public function __construct(private ChatJobService $jobs,private DcpToolRegistry $registry,private DcpCapabilityGrantService $grants,private DcpToolResultArtifactStore $artifacts,private PDO $db){}
 public function executeApprovedStep(string $jobId,string $stepKey,int $planVersion,string $expectedArgumentsHash):array{
  $job=$this->jobs->get($jobId);if(!in_array($job['status'],['completed','checkpoint_ready'],true))throw new RuntimeException('Tool execution is available only after the provider turn reaches a completed safe boundary.');
  $proposal=$this->jobs->getToolProposal($jobId,$stepKey,$planVersion);$tool=(string)($proposal['tool_name']??'');$capability=(string)($proposal['capability']??'');$classification=(string)($proposal['classification']??'');$args=$proposal['arguments']??null;$hash=(string)($proposal['arguments_hash']??'');
  if($tool===''||$capability===''||!is_array($args)||!preg_match('/^[a-f0-9]{64}$/',$hash)||!hash_equals($hash,$expectedArgumentsHash))throw new RuntimeException('Stored proposal metadata or arguments hash is invalid.');$policy=$this->registry->policy($tool);if(($policy['capability']??'')!==$capability||($policy['classification']??'')!==$classification)throw new RuntimeException('Tool policy changed since the plan was created. Replan and review.');
  if(!empty($proposal['approval_required']))$this->grants->assertGranted($jobId,$stepKey,$planVersion,$tool,$capability);elseif($classification!=='safe-read')throw new RuntimeException('Only safe-read tools may execute without a plan-bound approval and capability grant.');
  $claim=$this->jobs->claimToolExecution($jobId,$stepKey,$planVersion,$expectedArgumentsHash);if(($claim['status']??'')!=='claimed')return $claim;
  try{
   if(!empty($claim['approval_required']))$this->grants->assertGranted($jobId,$stepKey,$planVersion,$tool,$capability);
   $startedAudit=$this->db->prepare('INSERT INTO audit_log(event,details,created_at) VALUES(?,?,?)');$startedAudit->execute(['chat.tool_execution.started',json_encode(['job_id'=>$jobId,'step_key'=>$stepKey,'plan_version'=>$planVersion,'tool_name'=>$tool,'capability'=>$capability,'arguments_hash'=>$hash],JSON_UNESCAPED_UNICODE),date(DATE_ATOM)]);
   $result=$this->registry->call($tool,$claim['arguments'],['caller'=>'agent','capabilities'=>[$capability],'approval_status'=>!empty($claim['approval_required'])?'approved':'not_required','plan_version'=>$planVersion,'approval_plan_version'=>$planVersion,'approved_arguments_hash'=>$expectedArgumentsHash]);
   if(!is_array($result))$result=['value'=>$result];$artifact=$this->artifacts->store($jobId,$stepKey,$tool,$result);$completed=$this->jobs->completeToolExecution($jobId,$stepKey,$claim['execution_id'],$claim['lease_token'],$artifact['id'],$artifact['result_hash']);
   try{$q=$this->db->prepare('INSERT INTO audit_log(event,details,created_at) VALUES(?,?,?)');$q->execute(['chat.tool_execution.completed',json_encode(['job_id'=>$jobId,'step_key'=>$stepKey,'plan_version'=>$planVersion,'tool_name'=>$tool,'capability'=>$capability,'artifact_id'=>$artifact['id'],'result_hash'=>$artifact['result_hash']],JSON_UNESCAPED_UNICODE),date(DATE_ATOM)]);}catch(Throwable $auditError){/* The started audit record and completed execution ledger remain durable. */}
   return ['status'=>'completed','executed'=>true,'tool_name'=>$tool,'step_key'=>$stepKey,'artifact_id'=>$artifact['id'],'result_hash'=>$artifact['result_hash'],'result_bytes'=>$artifact['bytes'],'preview'=>$artifact['preview']];
  }catch(Throwable $e){try{$this->jobs->failToolExecution($jobId,$stepKey,$claim['execution_id'],$claim['lease_token'],$e->getMessage());}catch(Throwable $ignored){}try{$q=$this->db->prepare('INSERT INTO audit_log(event,details,created_at) VALUES(?,?,?)');$q->execute(['chat.tool_execution.failed',json_encode(['job_id'=>$jobId,'step_key'=>$stepKey,'plan_version'=>$planVersion,'tool_name'=>$tool,'error'=>mb_substr($e->getMessage(),0,500)],JSON_UNESCAPED_UNICODE),date(DATE_ATOM)]);}catch(Throwable $auditError){}throw $e;}
 }
 public function readResult(string $jobId,string $artifactId):array{$q=$this->db->prepare('SELECT 1 FROM chat_job_tool_results WHERE job_id=? AND result_ref=?');$q->execute([$jobId,$artifactId]);if(!$q->fetchColumn())throw new RuntimeException('Tool result is not attached to this chat job.');return $this->artifacts->read($artifactId);}
}
